3	/// An item a policy covers, as the office records it: the type it is listed
4	/// under in the price list, and the properties its clauses judge. The office
5	/// records an item's material because its reimbursement clauses speak of
6	/// items made of dragon material, and it is on the record of every insured
7	/// item whatever the clauses do with it. No clause reads the material: the
8	/// dragon-material clause reimburses in full, which is already what the
9	/// office admits when no clause reduces the damage, and where the clause
10	/// meets the enchantment clause the enchantment clause wins -- see
11	/// `reimbursable_damage_of`.
12	pub struct Item {
13	    pub item_type: String,
14	    pub cursed: bool,
15	    pub enchantment: i64,
16	    pub material: String,
17	}
18	
19	const PROCESSING_FEE: i64 = 5;
20	
21	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
22	const CURSE_SURCHARGE: f64 = 0.50;
23	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
24	const LOYALTY_DISCOUNT: f64 = 0.20;
25	const LOYALTY_YEARS: i64 = 2;
26	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
27	const HIGH_ENCHANTMENT_SURCHARGE_LEVEL: i64 = 5;
28	
29	const SWORD_BASE_PREMIUM: f64 = 100.0;
30	const AMULET_BASE_PREMIUM: f64 = 60.0;
31	const STAFF_BASE_PREMIUM: f64 = 80.0;
32	const POTION_BASE_PREMIUM: f64 = 40.0;
33	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
34	const SWORD_INSURANCE_VALUE: i64 = 1000;
35	const AMULET_INSURANCE_VALUE: i64 = 600;
36	const STAFF_INSURANCE_VALUE: i64 = 800;
37	const POTION_INSURANCE_VALUE: i64 = 400;
38	const COMPONENT_INSURANCE_VALUE: i64 = 250;
39	const PAYOUT_CAP_FACTOR: i64 = 2;
40	const DEDUCTIBLE: i64 = 100;
41	const HIGH_ENCHANTMENT_REIMBURSEMENT_LEVEL: i64 = 8;
42	const HIGH_ENCHANTMENT_REIMBURSEMENT: f64 = 0.50;
43	const COMPONENT_BLOCK_SIZE: usize = 3;
44	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
45	
46	/// The MHPCO treats components -- runes and moonstones -- as a category of
47	/// their own, priced per component rather than per type. Component types enter
48	/// this predicate with their examples.
49	fn is_component(item: &Item) -> bool {
50	    matches!(item.item_type.as_str(), "rune" | "moonstone")
51	}
52	
53	/// The MHPCO insures the item types its price list names and no others.
54	fn is_in_the_price_list(item_type: &str) -> bool {
55	    matches!(
56	        item_type,
57	        "sword" | "amulet" | "staff" | "potion" | "rune" | "moonstone"
58	    )
59	}
60	
61	/// The MHPCO price list: the base premium in G for a single insured item. Main
62	/// item types are listed individually; every component carries the same flat
63	/// component premium. All four main types now have their examples, and a quote
64	/// over an unlisted type is refused before it reaches the list, so the
65	/// remaining arm prices the sword and nothing else -- it is written as a
66	/// fall-through rather than as a `"sword"` arm because the list is closed and a
67	/// `"sword"` arm would leave an unreachable residual behind it.
68	fn base_premium_of(item: &Item) -> f64 {
69	    if is_component(item) {
70	        return COMPONENT_BASE_PREMIUM;
71	    }
72	    match item.item_type.as_str() {
73	        "amulet" => AMULET_BASE_PREMIUM,
74	        "staff" => STAFF_BASE_PREMIUM,
75	        "potion" => POTION_BASE_PREMIUM,
76	        _ => SWORD_BASE_PREMIUM,
77	    }
78	}
79	
80	/// What the customer's standing with the office is worth, as a single share of
81	/// the policy base premium. The office was asked whether "first insurance"
82	/// means the customer's first ever contract or the first time it sees this
83	/// item, and ruled for the item: every item in a quote is treated as a first
84	/// insurance, so the initial assessment surcharge is unconditional and a
85	/// long-standing customer pays it on a brand-new sword like anyone else. What
86	/// the years of business earn is the loyalty discount, taken against that
87	/// surcharge. This is the office's customer-history policy, and the rest of
88	/// the premium calculation does not need to know which clauses it is made of.
89	fn policy_modifier_rate_of(history: &CustomerHistory) -> f64 {
90	    let mut modifier_rate = FIRST_INSURANCE_SURCHARGE;
91	    if history.customer.years_with_mhpco >= LOYALTY_YEARS {
92	        modifier_rate -= LOYALTY_DISCOUNT;
93	    }
94	    if history.preceding_contracts > 0 {
95	        modifier_rate -= FOLLOW_UP_CONTRACT_DISCOUNT;
96	    }
97	    modifier_rate
98	}
99	
100	/// Policy-wide modifiers apply to the policy base premium, the sum of all item
101	/// base premiums, at the single rate the customer's standing earns.
102	fn with_policy_modifiers(history: &CustomerHistory, policy_base_premium: f64) -> f64 {
103	    policy_base_premium + policy_base_premium * policy_modifier_rate_of(history)
104	}
105	
106	/// A building block of 3 alike components is offered at a special base premium
107	/// instead of the per-component price.
108	fn alike_components_base_premium(count: usize) -> f64 {
109	    if count == COMPONENT_BLOCK_SIZE {
110	        return COMPONENT_BLOCK_BASE_PREMIUM;
111	    }
112	    count as f64 * COMPONENT_BASE_PREMIUM
113	}
114	
115	/// The policy base premium is the sum of all item base premiums, except that
116	/// alike components are priced together so the block offer can apply.
117	fn policy_base_premium_of(items: &[Item]) -> f64 {
118	    let main_items: f64 = items
119	        .iter()
120	        .filter(|item| !is_component(item))
121	        .map(base_premium_of)
122	        .sum();
123	    let components: f64 = alike_component_groups_of(items)
124	        .into_iter()
125	        .map(alike_components_base_premium)
126	        .sum();
127	    main_items + components
128	}
129	
130	/// Components count as alike when they are of exactly the same type, not
131	/// merely of the same family: a policy of 2 runes and 1 moonstone forms no
132	/// block, so the office prices the two kinds separately. This groups a
133	/// policy's components by type and reports how many are in each group, in
134	/// order of the groups' first appearance.
135	fn alike_component_groups_of(items: &[Item]) -> Vec<usize> {
136	    let mut groups: Vec<(&str, usize)> = Vec::new();
137	    for item in items.iter().filter(|item| is_component(item)) {
138	        match groups.iter_mut().find(|(alike, _)| *alike == item.item_type) {
139	            Some((_, count)) => *count += 1,
140	            None => groups.push((&item.item_type, 1)),
141	        }
142	    }
143	    groups.into_iter().map(|(_, count)| count).collect()
144	}
145	
146	/// Only the final premium is rounded, and a premium is rounded up -- the
147	/// MHPCO's favor for money it collects. The processing fee is added at the very
148	/// end; being a whole number of G, it does not affect the rounding.
149	fn total_premium_of(premium_before_fee: f64) -> i64 {
150	    premium_before_fee.ceil() as i64 + PROCESSING_FEE
151	}
152	
153	/// The office was asked whether a risk surcharge on one item of a multi-item
154	/// policy burdens the whole policy, and ruled that it does not: an
155	/// item-specific modifier is measured against the base premium of the affected
156	/// item alone. A policy of a cursed sword and a plain amulet therefore carries
157	/// a curse surcharge of 50 G -- 50 % of the sword's own 100 G base premium --
158	/// and not 80 G, half of the 160 G policy base premium.
159	fn item_surcharges_of(items: &[Item]) -> f64 {
160	    items.iter().map(item_surcharge_of).sum()
161	}
162	
163	/// The risk surcharges an item carries: a curse adds 50 %, an enchantment at
164	/// or above the surcharge level adds 30 %, and an item that is both carries
165	/// both. The surcharge level is the premium side's own threshold; the claim
166	/// side judges enchantment against a separate level of its own.
167	fn item_surcharge_of(item: &Item) -> f64 {
168	    let mut surcharge_rate = 0.0;
169	    if item.cursed {
170	        surcharge_rate += CURSE_SURCHARGE;
171	    }
172	    if item.enchantment >= HIGH_ENCHANTMENT_SURCHARGE_LEVEL {
173	        surcharge_rate += HIGH_ENCHANTMENT_SURCHARGE;
174	    }
175	    base_premium_of(item) * surcharge_rate
176	}
177	
178	/// How the two modifier families stack. By the office's scope ruling they are
179	/// measured against different bases, so they cannot be combined into one
180	/// percentage: the policy-wide modifiers scale the policy base premium, while
181	/// the item surcharges are shares of their own items' base premiums and are
182	/// added alongside. A cursed sword is therefore 100 + 10 % of 100 + 50 % of
183	/// 100, not 10 % of 150; a cursed sword beside a plain amulet is 160 + 10 % of
184	/// 160 + 50 % of 100.
185	fn premium_before_fee_of(history: &CustomerHistory, items: &[Item]) -> f64 {
186	    with_policy_modifiers(history, policy_base_premium_of(items)) + item_surcharges_of(items)
187	}
