189	/// The single customer a scenario's policies belong to.
190	pub struct Customer {
191	    pub years_with_mhpco: i64,
192	}
193	
194	/// The office's view of the customer at the moment of a quote: who they are
195	/// and how many contracts they already hold. The preceding-contract count is
196	/// not a property of the customer -- a scenario has one customer whose steps
197	/// are processed in order, so the count is what the office has on file when
198	/// this particular quote is drawn up. Together these are the facts the
199	/// customer-history policy reads.
200	pub struct CustomerHistory<'a> {
201	    pub customer: &'a Customer,
202	    pub preceding_contracts: usize,
203	}
