205	/// The MHPCO price list: the insurance value in G of a single insured item --
206	/// the worth the office acknowledges when it pays out, as opposed to the price
207	/// it charges to carry the risk. The price list prints the two figures side by
208	/// side, but they are separate rulings and move separately: the block offer and
209	/// the premium modifiers both change what an item costs to insure while leaving
210	/// its acknowledged worth untouched. So this list stays apart from the base
211	/// premium list rather than being derived from it. Both columns are now
212	/// complete: all four main types have their acknowledged worth on file, and a
213	/// claim or quote over an unlisted type is refused before it reaches the list,
214	/// so the remaining arm values the sword and nothing else -- a fall-through
215	/// rather than a `"sword"` arm for the same reason the base premium list uses
216	/// one, the list being closed.
217	fn insurance_value_of(item: &Item) -> i64 {
218	    if is_component(item) {
219	        return COMPONENT_INSURANCE_VALUE;
220	    }
221	    match item.item_type.as_str() {
222	        "amulet" => AMULET_INSURANCE_VALUE,
223	        "staff" => STAFF_INSURANCE_VALUE,
224	        "potion" => POTION_INSURANCE_VALUE,
225	        _ => SWORD_INSURANCE_VALUE,
226	    }
227	}
228	
229	/// The insurance sum is the sum of the insured items' insurance values. The
230	/// block offer discounts the premium only, never the insurance sum.
231	fn insurance_sum_of(items: &[Item]) -> i64 {
232	    items.iter().map(insurance_value_of).sum()
233	}
