235	/// What the office reports for one processed step of a scenario.
236	#[derive(Debug, PartialEq, Eq)]
237	pub enum StepResult {
238	    Quote { premium: i64 },
239	    Claim { payout: i64, remaining_cap: i64 },
240	}
