278	#[derive(Deserialize)]
279	#[serde(rename_all = "camelCase")]
280	struct Incident {
281	    /// The office records what an incident was caused by, because the schema
282	    /// names `cause` among an incident's fields and binds that name. No clause
283	    /// of the price list or of the reimbursement rules reads it: what the
284	    /// office pays turns on the damaged item and the amount, never on whether
285	    /// the dragon attacked or the fire spread. The field stays on the document
286	    /// type all the same, so that type mirrors the schema it transcribes
287	    /// rather than only the part the clauses happen to consult. A clause that
288	    /// priced or reimbursed by cause would be the change that makes it read;
289	    /// until then the office asks nothing of a report that omits it, no
290	    /// example calling for such a report to be refused.
291	    #[allow(dead_code, reason = "bound by the normative input schema; no clause reads it")]
292	    cause: String,
293	    damages: Vec<ReportedDamage>,
294	}
