303	/// What one step of a scenario instructs the office to do, in the office's own
304	/// terms: draw up a policy over these insured items, or settle a claim of
305	/// these damages against the policy a named earlier step created. This is the
306	/// scenario's content once the document it arrived in has been read -- the
307	/// office processes instructions, not JSON, so the field names the schema
308	/// binds and the `serde` attributes that carry them stay on the document side
309	/// in `Step` and do not reach the processing rules.
310	enum Instruction {
311	    Quote { items: Vec<Item> },
312	    Claim { policy: usize, damages: Vec<Damage> },
313	}
314	
315	/// A policy a quote step drew up: the items it insures and the running
316	/// account of what the office has paid out on it. The account is part of the
317	/// policy and not of the scenario that processes it, because the cap is a
318	/// per-policy total: the specification has a sword's policy answer two claims
319	/// of 1500 G with 1400 G and then 600 G, so what an earlier claim drew is a
320	/// fact the policy itself carries into the next one.
321	struct DrawnUpPolicy {
322	    insured_items: Vec<Item>,
323	    paid_so_far: i64,
324	}
325	
326	impl DrawnUpPolicy {
327	    /// Settles a claim of these damages against this policy, which is one
328	    /// act and not two: the cap still available is what the policy has not
329	    /// yet paid, and a payout the office awards is paid out of it. So the
330	    /// policy's account is read and advanced here, where the settlement
331	    /// happens, rather than by the scenario that asks for it -- the
332	    /// specification's successive claims draw the cap down by what was
333	    /// actually awarded, which is a ruling of the cap and not of the step
334	    /// order. A reinstatement that restored part of the cap, or a cap drawn
335	    /// down by the desired rather than the awarded payout, would change this
336	    /// and nothing about how a scenario's steps are sequenced.
337	    fn settle_a_claim_of(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
338	        let settlement = claim(&self.insured_items, self.paid_so_far, damages)?;
339	        self.paid_so_far += settlement.payout;
340	        Ok(settlement)
341	    }
342	}
343	
344	/// The office's file of drawn-up policies, in which a policy is named by the
345	/// step that drew it up. The office was asked what a claim's `policy` names
346	/// and ruled for the step: the zero-based index of the quote step, not the
347	/// position of the policy among those drawn up -- a quote at step 2 is named
348	/// 2 even when it is only the second policy on file. So each policy is filed
349	/// under the number of the step that drew it up and found again by it. The
350	/// name is kept as a fact of the policy rather than left to its place in the
351	/// file, because the two differ: a scenario whose steps alternate quote and
352	/// claim files its second policy under 2, and only a recorded name says so.
353	///
354	/// The file answers two of the office's questions, and it is one fact asked
355	/// from two sides rather than two facts kept in step: a contract exists
356	/// exactly because a quote filed a policy, so the policies on file ARE the
357	/// contracts the customer holds. A claim reads the file by step to find the
358	/// policy to settle against; a quote asks how many policies stand on file to
359	/// learn how many contracts precede this one, which is what earns the
360	/// follow-up contract discount. The count is read off the file rather than
361	/// tallied beside it, so it cannot drift from what the file says. Only a
362	/// quote the office did not refuse reaches the file, so a refused quote is
363	/// neither claimable against nor counted as a preceding contract -- the same
364	/// ruling for both readings, because it is the same record.
365	#[derive(Default)]
366	struct PolicyFile {
367	    drawn_up: Vec<(usize, DrawnUpPolicy)>,
368	}
369	
370	impl PolicyFile {
371	    /// Files a policy over these items under the number of the quote step
372	    /// that drew it up, which is the name a later claim calls it by.
373	    fn draw_up_a_policy_over(&mut self, drawn_up_by_step: usize, insured_items: Vec<Item>) {
374	        self.drawn_up.push((
375	            drawn_up_by_step,
376	            DrawnUpPolicy {
377	                insured_items,
378	                paid_so_far: 0,
379	            },
380	        ));
381	    }
382	
383	    /// The policy a named step drew up, or the office's refusal when no step
384	    /// of that number drew one up.
385	    fn policy_drawn_up_by(&mut self, step: usize) -> Result<&mut DrawnUpPolicy, String> {
386	        self.drawn_up
387	            .iter_mut()
388	            .find(|(drawn_up_by_step, _)| *drawn_up_by_step == step)
389	            .map(|(_, policy)| policy)
390	            .ok_or_else(|| format!("no policy was created by step {step}"))
391	    }
392	
393	    /// How many contracts the customer holds: one per policy on file.
394	    fn contracts_on_file(&self) -> usize {
395	        self.drawn_up.len()
396	    }
397	}
