399	/// Processes a scenario's instructions in order and reports one result per
400	/// instruction. This is the office's scenario policy, and only that: the steps
401	/// are processed sequentially, each quote draws up a policy that a later claim
402	/// can name, and the premium a quote is charged depends on what the customer
403	/// already holds. Which policy a named step drew up, and how a step's number
404	/// becomes its policy's name, is the file's own knowledge -- see `PolicyFile`.
405	fn process_the_instructions(
406	    customer: &Customer,
407	    instructions: Vec<Instruction>,
408	) -> Result<Vec<StepResult>, String> {
409	    let mut results = Vec::new();
410	    let mut policies = PolicyFile::default();
411	    for (step, instruction) in instructions.into_iter().enumerate() {
412	        results.push(match instruction {
413	            Instruction::Quote { items } => {
414	                let history = CustomerHistory {
415	                    customer,
416	                    preceding_contracts: policies.contracts_on_file(),
417	                };
418	                let premium = quote(&history, &items)?;
419	                policies.draw_up_a_policy_over(step, items);
420	                StepResult::Quote { premium }
421	            }
422	            Instruction::Claim { policy, damages } => {
423	                let drawn_up = policies.policy_drawn_up_by(policy)?;
424	                let settlement = drawn_up.settle_a_claim_of(&damages)?;
425	                StepResult::Claim {
426	                    payout: settlement.payout,
427	                    remaining_cap: settlement.remaining_cap,
428	                }
429	            }
430	        });
431	    }
432	    Ok(results)
433	}
