435	/// Reads a scenario document, settles it, and writes the results document the
436	/// office publishes.
437	pub fn settle_the_scenario(scenario: &str) -> Result<String, String> {
438	    let results = run_scenario(scenario)?;
439	    let published = PublishedResults {
440	        results: results.iter().map(PublishedResult::from).collect(),
441	    };
442	    serde_json::to_string(&published).map_err(|error| error.to_string())
443	}
