451	/// One step's result as the office publishes it. The field names are the ones
452	/// the specification binds, so they are spelled here rather than derived.
453	#[derive(Serialize)]
454	#[serde(untagged)]
455	enum PublishedResult {
456	    Quote {
457	        premium: i64,
458	    },
459	    Claim {
460	        payout: i64,
461	        #[serde(rename = "remainingCap")]
462	        remaining_cap: i64,
463	    },
464	}
465	
466	impl From<&StepResult> for PublishedResult {
467	    fn from(result: &StepResult) -> Self {
468	        match *result {
469	            StepResult::Quote { premium } => PublishedResult::Quote { premium },
470	            StepResult::Claim {
471	                payout,
472	                remaining_cap,
473	            } => PublishedResult::Claim {
474	                payout,
475	                remaining_cap,
476	            },
477	        }
478	    }
479	}
