481	/// Reads a scenario document and reports one result per step. This is the
482	/// office's reading desk: it takes the document apart into the customer and
483	/// the instructions its steps give, and hands those to the processing rules.
484	pub fn run_scenario(scenario: &str) -> Result<Vec<StepResult>, String> {
485	    let scenario: Scenario = serde_json::from_str(scenario).map_err(|error| error.to_string())?;
486	    let customer = Customer {
487	        years_with_mhpco: scenario.customer.years_with_mhpco,
488	    };
489	    let instructions: Vec<Instruction> = scenario.steps.iter().map(instruction_of).collect();
490	    process_the_instructions(&customer, instructions)
491	}
