493	/// Translates one reported step into the instruction it gives the office.
494	fn instruction_of(step: &Step) -> Instruction {
495	    match step {
496	        Step::Quote { items } => Instruction::Quote {
497	            items: insured_items_of(items),
498	        },
499	        Step::Claim { policy, incident } => Instruction::Claim {
500	            policy: *policy,
501	            damages: reported_damages_of(&incident.damages),
502	        },
503	    }
504	}
