506	/// Translates the items a quote step reports into insured items.
507	fn insured_items_of(reported: &[ReportedItem]) -> Vec<Item> {
508	    reported
509	        .iter()
510	        .map(|item| Item {
511	            item_type: item.item_type.clone(),
512	            cursed: item.cursed,
513	            enchantment: item.enchantment,
514	            material: item.material.clone(),
515	        })
516	        .collect()
517	}
518	
519	/// Translates the damages an incident reports into damages.
520	fn reported_damages_of(reported: &[ReportedDamage]) -> Vec<Damage> {
521	    reported
522	        .iter()
523	        .map(|damage| Damage {
524	            item_type: damage.item_type.clone(),
525	            amount: damage.amount,
526	        })
527	        .collect()
528	}
