544	/// The office takes no damage report for a negative amount: a damage is what
545	/// the incident cost, so a negative figure is not a smaller claim but an
546	/// unreadable report, and the whole claim is refused.
547	fn admit_the_reported_damages(damages: &[Damage]) -> Result<(), String> {
548	    match damages.iter().find(|damage| damage.amount < 0) {
549	        Some(damage) => Err(format!("negative damage amount: {}", damage.amount)),
550	        None => Ok(()),
551	    }
552	}
553	
554	/// How the office settles a claim against this policy. One incident may
555	/// damage several insured items, and the office settles each damaged item on
556	/// its own terms before adding the amounts up: a dragon attack on a sword and
557	/// an amulet is settled as two damages, not as one. The awarded sum is then
558	/// held back to the cap still available, which is the policy's cap less what
559	/// earlier claims have already drawn on it -- a policy may be claimed against
560	/// more than once, so what has been paid so far is a fact of every claim, nil
561	/// on the first.
562	pub fn claim(
563	    items: &[Item],
564	    paid_so_far: i64,
565	    damages: &[Damage],
566	) -> Result<Settlement, String> {
567	    admit_the_reported_damages(damages)?;
568	    let cap_available = payout_cap_of(items)? - paid_so_far;
569	    let payout = desired_payout_of(items, damages)?.min(cap_available);
570	    Ok(Settlement {
571	        payout,
572	        remaining_cap: cap_available - payout,
573	    })
574	}
575	
576	/// What the reimbursement clauses award for an incident, before the policy's
577	/// cap is consulted. The office settles each damaged item on its own terms and
578	/// adds the amounts up; this is the sum the office desires to pay, which the
579	/// cap may then hold back -- the spec speaks of a desired payout being reduced
580	/// to the cap remaining, so the awarded sum is a figure of its own and not
581	/// merely an intermediate step inside the cap accounting.
582	///
583	/// The insured items start out unanswered and each assignment strikes one off,
584	/// which is how the office holds an insured item to a single damage; see
585	/// `insured_item_answering`.
586	fn desired_payout_of(items: &[Item], damages: &[Damage]) -> Result<i64, String> {
587	    let mut unanswered: Vec<&Item> = items.iter().collect();
588	    let mut desired_payout = 0;
589	    for damage in damages {
590	        let damaged_item = insured_item_answering(&mut unanswered, damage)?;
591	        desired_payout += reimbursement_of(damaged_item, damage);
592	    }
593	    Ok(desired_payout)
594	}
595	
596	/// Which insured item answers a reported damage, and when the office refuses
597	/// the claim instead. An insured item answers at most one damage: a policy
598	/// covering one sword cannot answer two sword damages. The office enforces
599	/// that by striking the item it assigns off the list of those still
600	/// unanswered, so each damage is assigned an item of its own and a policy
601	/// covering two swords answers two sword damages.
602	///
603	/// Both ways a damage can fail to be assigned are refused in the same words,
604	/// naming the type: a policy that covers no sword at all and a policy whose
605	/// only sword has already answered an earlier damage are, from the claim's
606	/// side, the same objection -- this damage has no insured item to be settled
607	/// against, so the office declines to cover it and refuses the claim whole.
608	/// The office is asked only for a refusal the CLI can report and exit on, and
609	/// it has no finer ruling to make between the two grounds. A ruling that did
610	/// distinguish them -- different wording per ground, or refusing only the
611	/// surplus damage rather than the whole claim -- would be the change that
612	/// splits this into two objections.
613	fn insured_item_answering<'a>(
614	    unanswered: &mut Vec<&'a Item>,
615	    damage: &Damage,
616	) -> Result<&'a Item, String> {
617	    let position = unanswered
618	        .iter()
619	        .position(|item| item.item_type == damage.item_type);
620	    match position {
621	        Some(position) => Ok(unanswered.remove(position)),
622	        None => Err(format!(
623	            "item not covered by the policy: {}",
624	            damage.item_type
625	        )),
626	    }
627	}
628	
629	/// What the office reimburses for one damaged item: the damage amount less the
630	/// deductible. The office charges the deductible per damage event, and it
631	/// counts each damaged item as a damage event of its own -- two items damaged
632	/// by a single dragon attack bear the deductible twice, once each.
633	fn reimbursement_of(damaged_item: &Item, damage: &Damage) -> i64 {
634	    reimbursable_damage_of(damaged_item, damage) - DEDUCTIBLE
635	}
636	
637	/// How much of the reported damage the office admits before the deductible --
638	/// which of its reimbursement clauses governs, and what that clause admits.
639	/// The office has two: damage to an item enchanted at or above the
640	/// reimbursement level is admitted at half, and damage to an item made of
641	/// dragon material is reimbursed in full. Only the enchantment clause appears
642	/// as a branch here, and that is the whole clause set faithfully, not a
643	/// clause left out:
644	///
645	/// - Full reimbursement IS the dragon-material outcome, and it is also what
646	///   the office admits when no clause reduces the damage. The two clauses
647	///   therefore differ in which items they name, not in what they pay, so a
648	///   separate dragon-material branch would compute the same amount the
649	///   fall-through already computes.
650	/// - Where both clauses name the same item, the halving clause governs: a
651	///   dragon-material sword enchanted at the reimbursement level is admitted at
652	///   half, not in full. Ranking the enchantment clause first is what makes the
653	///   collapse above sound, because it leaves the dragon clause reachable only
654	///   where it agrees with the fall-through.
655	///
656	/// So this stays one decision with one discriminating predicate. A third
657	/// clause, or a clause whose share were neither half nor full, would break the
658	/// collapse and force the clause set to become visible structure.
659	///
660	/// The reimbursement level is the claim side's own threshold, set higher than
661	/// the level at which the premium side charges a risk surcharge: the office
662	/// surcharges an enchantment of 5 but only halves its reimbursement from 8.
663	fn reimbursable_damage_of(damaged_item: &Item, damage: &Damage) -> i64 {
664	    let highly_enchanted =
665	        damaged_item.enchantment >= HIGH_ENCHANTMENT_REIMBURSEMENT_LEVEL;
666	    if highly_enchanted {
667	        return admitted_damage_of(damage.amount as f64 * HIGH_ENCHANTMENT_REIMBURSEMENT);
668	    }
669	    damage.amount
670	}
671	
672	/// An admitted damage is rounded down -- the MHPCO's favor for money it pays
673	/// out, the mirror of the rounding up a premium gets in `total_premium_of`.
674	/// This is the office's house-wide favor ruling, not a reimbursement clause:
675	/// it is the direction a fraction is resolved in, whatever clause produced the
676	/// fraction. Rounding sits here, at the halving clause, because that clause is
677	/// the only step of a settlement that can yield a fraction at all -- the
678	/// deductible, the insurance values and the cap are whole G throughout -- so
679	/// rounding the share the office admits and rounding the final payout are the
680	/// same figure. A clause admitting some other share would arrive here too; a
681	/// fractional deductible or cap would move the ruling to the final payout.
682	fn admitted_damage_of(admitted_share: f64) -> i64 {
683	    admitted_share.floor() as i64
684	}
685	
686	/// The total payout per policy is capped at twice the insurance sum.
687	pub fn payout_cap_of(items: &[Item]) -> Result<i64, String> {
688	    Ok(insurance_sum_of(items) * PAYOUT_CAP_FACTOR)
689	}
690	
691	/// Whether the office will entertain a policy over these items at all. The
692	/// office insures the types its price list names and no others, so an item it
693	/// does not recognise is refused rather than priced -- a quote that lists a
694	/// broomstick yields no premium. The office names the offending type in its
695	/// refusal; which types it admits is the price list's own knowledge, read
696	/// here rather than restated.
697	fn admit_the_listed_items(items: &[Item]) -> Result<(), String> {
698	    match items
699	        .iter()
700	        .find(|item| !is_in_the_price_list(&item.item_type))
701	    {
702	        Some(unlisted) => Err(format!("unknown item type: {}", unlisted.item_type)),
703	        None => Ok(()),
704	    }
705	}
706	
707	/// The premium in G the office charges for insuring these items, given what it
708	/// has on file about the customer.
709	///
710	/// A refusal is carried as the office's own description of what it objects to.
711	/// The office refuses documents for several unrelated reasons -- an unlisted
712	/// item type here, a damage outside the policy on the claim side -- but no
713	/// caller distinguishes them: the specification asks only that a refusal reach
714	/// stderr and the exit status be non-zero, so every reason is rendered the same
715	/// way. A named error type would be built at each refusal and flattened back to
716	/// its description at the one place that reports it, which relocates the
717	/// wording without giving any caller a decision it can make. A caller that had
718	/// to tell the reasons apart -- a different exit code per reason, a retry on
719	/// some but not others -- would be the change that earns the type.
720	pub fn quote(history: &CustomerHistory, items: &[Item]) -> Result<i64, String> {
721	    admit_the_listed_items(items)?;
722	    Ok(total_premium_of(premium_before_fee_of(history, items)))
723	}
724	
